<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateEnabledVO;

trait TemplateEnabledAccessor
{
    private ?TemplateEnabledVO $_enabled = null;
    public function isEnabled(): ?bool
    {
        return $this->_enabled?->value();
    }
    public function enabled(): ?TemplateEnabledVO
    {
        return $this->_enabled;
    }
    public function isEnabledChanged(?self $original = null): bool
    {
        return null !== $this->_enabled && !$this->_enabled->equals($original?->_enabled);
    }
    public function withEnabled(TemplateEnabledVO|bool|null $enabled): self
    {
        $copy = clone $this;
        $copy->_enabled = TemplateEnabledVO::from($enabled);
        return $copy;
    }
}
